// Content with portions generated by generative AI platform
package org.eclipse.kura.web.server.util;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.eclipse.kura.configuration.ComponentConfiguration;
import org.eclipse.kura.core.configuration.ComponentConfigurationImpl;
import org.eclipse.kura.web.shared.GwtKuraErrorCode;
import org.eclipse.kura.web.shared.GwtKuraException;
import org.eclipse.kura.web.shared.model.GwtConfigComponent;
import org.junit.Test;

/**
 * Feature: the Driver configurations received together with a Wire Graph update from the Web UI can only modify
 * existing components that are actually instances of the declared factory.
 */
public class WireAdditionalConfigurationsValidationTest {

    private static final String USER_STORE_PID = "org.eclipse.kura.internal.useradmin.store.RoleRepositoryStoreImpl";
    private static final String DRIVER_FACTORY_PID = "org.eclipse.kura.driver.opcua";
    private static final String OTHER_DRIVER_FACTORY_PID = "org.eclipse.kura.driver.s7plc";
    private static final String DRIVER_PID = "myDriver";

    private final List<GwtConfigComponent> receivedConfigs = new ArrayList<>();
    private final Map<String, ComponentConfiguration> existingConfigs = new HashMap<>();
    private GwtKuraException occurredException;

    /*
     * Scenarios
     */

    @Test
    public void rejectsNonFactoryComponentDeclaredAsDriver() {
        givenExistingComponent(USER_STORE_PID, null);
        givenReceivedConfiguration(USER_STORE_PID, DRIVER_FACTORY_PID);

        whenReceivedConfigurationsAreValidated();

        thenIllegalArgumentIsReported();
    }

    @Test
    public void rejectsDriverDeclaredWithAnotherFactory() {
        givenExistingComponent(DRIVER_PID, DRIVER_FACTORY_PID);
        givenReceivedConfiguration(DRIVER_PID, OTHER_DRIVER_FACTORY_PID);

        whenReceivedConfigurationsAreValidated();

        thenIllegalArgumentIsReported();
    }

    @Test
    public void acceptsDriverDeclaredWithItsFactory() {
        givenExistingComponent(DRIVER_PID, DRIVER_FACTORY_PID);
        givenReceivedConfiguration(DRIVER_PID, DRIVER_FACTORY_PID);

        whenReceivedConfigurationsAreValidated();

        thenNoExceptionOccurred();
    }

    @Test
    public void acceptsNotExistingComponent() {
        givenReceivedConfiguration(DRIVER_PID, DRIVER_FACTORY_PID);

        whenReceivedConfigurationsAreValidated();

        thenNoExceptionOccurred();
    }

    /*
     * Steps
     */

    /*
     * Given
     */

    private void givenExistingComponent(final String pid, final String factoryPid) {
        final Map<String, Object> properties = new HashMap<>();
        properties.put("kura.service.pid", pid);
        if (factoryPid != null) {
            properties.put("service.factoryPid", factoryPid);
        }
        this.existingConfigs.put(pid, new ComponentConfigurationImpl(pid, null, properties));
    }

    private void givenReceivedConfiguration(final String pid, final String factoryPid) {
        final GwtConfigComponent config = new GwtConfigComponent();
        config.setComponentId(pid);
        config.setFactoryPid(factoryPid);
        this.receivedConfigs.add(config);
    }

    /*
     * When
     */

    private void whenReceivedConfigurationsAreValidated() {
        try {
            GwtServerUtil.requireMatchingFactoryPids(this.receivedConfigs, this.existingConfigs);
        } catch (final GwtKuraException e) {
            this.occurredException = e;
        }
    }

    /*
     * Then
     */

    private void thenIllegalArgumentIsReported() {
        assertNotNull("expected the configuration to be rejected", this.occurredException);
        assertEquals(GwtKuraErrorCode.ILLEGAL_ARGUMENT, this.occurredException.getCode());
    }

    private void thenNoExceptionOccurred() {
        assertNull(this.occurredException);
    }
}
